"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";

// Description List: generated by UIX from the design system. Same variants and sizes as the Figma component.

export interface DescriptionItem {
  term: React.ReactNode;
  detail: React.ReactNode;
}

const descriptionListVariants = cva(
  "flex w-full flex-col divide-y overflow-hidden divide-line-subtle bg-surface border border-line-default [&>div]:flex [&>div]:px-6 [&>div]:py-4 [&_dt]:text-label-medium [&_dt]:text-fg-secondary [&_dd]:text-body-medium [&_dd]:text-fg-primary [&_dd]:min-w-0 [&_dd]:flex-1 rounded-xl",
  {
    variants: {
      layout: {
        horizontal: "[&>div]:flex-row [&>div]:items-start [&>div]:gap-4 [&_dt]:w-40 [&_dt]:shrink-0",
        stacked: "[&>div]:flex-col [&>div]:gap-1",
      },
    },
    defaultVariants: {
      layout: "horizontal",
    },
  },
);

export interface DescriptionListProps
  extends React.HTMLAttributes<HTMLDListElement>,
    VariantProps<typeof descriptionListVariants> {
  /** Rows of label + value. A Badge works as a value (a status). */
  items: DescriptionItem[];
}

const DescriptionList = React.forwardRef<HTMLDListElement, DescriptionListProps>(
  ({ className, layout, items, ...props }, ref) => (
    <dl data-slot="description-list" data-kind="surface" ref={ref} className={cn(descriptionListVariants({ layout }), className)} {...props}>
      {items.map((item, index) => (
        <div key={index}>
          <dt>{item.term}</dt>
          <dd>{item.detail}</dd>
        </div>
      ))}
    </dl>
  ),
);
DescriptionList.displayName = "DescriptionList";

export { DescriptionList, descriptionListVariants };
